ICONS = {'grid': '<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>', 'run': '<path d="m9 5 11 7-11 7z"/><path d="M4 5v14"/>', 'rules': '<path d="M8 4h11v17H5V4h3m0-2h8v5H8zM9 12h6M9 16h6"/>', 'rank': '<path d="M5 20v-7h4v7m2 0V4h4v16m2 0V9h4v11M3 20h19"/>', 'review': '<path d="M20 11v9H4V4h11m-6 7 4 4L22 6"/>', 'settings': '<path d="M4 7h16M4 17h16M8 4v6m8 4v6"/>', 'molecule': '<path d="m7 6 10 0 5 8-5 8H7l-5-8zM7 6l5 8m5-8-5 8m0 0 5 8m-5-8-5 8"/><circle cx="7" cy="6" r="2"/><circle cx="17" cy="6" r="2"/><circle cx="12" cy="14" r="2"/>', 'search': '<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>'}

def icon(name: str) -> str:
    return f"""<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{ICONS.get(name, ICONS['grid'])}</svg>"""

def esc(value: Any) -> str:
    return html.escape(str(value if value is not None else '—'), quote=True)

def short(value: Any, length: int=14) -> str:
    value = str(value or _ui('未选择任务'))
    return value if len(value) <= length + 7 else value[:length] + '…' + value[-5:]
TITLES = {'tasks and runs': '研究工作台', 'leaderboard': '候选排名', 'candidate': '候选与证据', 'run': '运行监控', 'review queue': '复核队列', 'criteria pool': '研究标准', 'settings': '工作区设置'}

def chrome(title: str, target: str, body: str, context: dict[str, Any] | None=None) -> str:
    data = context or {}
    split = urlsplit(target)
    task_id = data.get('task_id') or data.get('_navigation_task') or (parse_qs(split.query).get('task') or [None])[0]
    tasks = data.get('tasks') or []
    if not task_id and tasks:
        task_id = tasks[-1]['task_id']
    task_query = '?' + urlencode({'task': task_id}) if task_id else ''
    selected = {'/candidate': '/leaderboard', '/run': '/operations'}.get(split.path, split.path)
    nav = []
    for path, name, glyph in (('/', _ui('任务总览'), 'grid'), ('/operations', _ui('运行与操作'), 'run'), ('/pool', _ui('研究标准'), 'rules'), ('/leaderboard', _ui('候选排名'), 'rank'), ('/review', _ui('复核队列'), 'review'), ('/settings', _ui('工作区设置'), 'settings')):
        parameters = {'lang': LANGUAGE.get()}
        if task_id:
            parameters['task'] = task_id
        href = path + '?' + urlencode(parameters)
        active = ' aria-current="page"' if path == selected else ''
        task_route = f' data-task-route="{path}"'
        nav.append(f'<a class="nav-link" href="{esc(href)}"{active}{task_route}>{icon(glyph)}<span>{name}</span><span class="nav-arrow">›</span></a>')
    twin = '/api' + ('' if target in ('/', '') else target)
    if data.get('scope') == 'task' and data.get('task_id') and ('task' not in parse_qs(urlsplit(twin).query)):
        twin += ('&' if '?' in twin else '?') + urlencode({'task': data['task_id']})
    if data.get('routes_included') is False:
        twin += ('&' if '?' in twin else '?') + 'routes=0'
    if data.get('current_versions_only') and 'current_versions' not in parse_qs(urlsplit(twin).query):
        twin += ('&' if '?' in twin else '?') + 'current_versions=1'
    display_title = _ui(TITLES.get(title, title))
    stamp = data.get('as_of')
    footer = f'''{_ui('<footer class="page-footer"><span>MAS · 基于已记录的研究状态</span><span>')}{(esc(stamp) if stamp else _ui('本机工作区'))} · <a href="{esc(twin)}" title="this page as JSON">Data</a></span></footer>'''
    task_json = json.dumps(task_id or '')
    script = '<script type="module">\nconst selectedTask = TASK;\nfunction syncTaskNavigation(task, updateLocation=false) {\n  if (!task) return;\n  for (const link of document.querySelectorAll(\'[data-task-route],.language-switch a,a.brand,.sidebar-context a\')) {const url=new URL(link.href,location.origin);url.searchParams.set(\'task\',task);if(link.closest(\'.language-switch\'))url.hash=location.hash;link.href=url.pathname+url.search+url.hash;}\n  if(updateLocation){const url=new URL(location.href);url.searchParams.set(\'task\',task);history.replaceState(history.state,\'\',url.pathname+url.search+url.hash);}\n  const label = document.getElementById(\'sidebar-task\');\n  if (label) {label.textContent = task.length > 25 ? task.slice(0,14)+\'…\'+task.slice(-5) : task; label.title = task;}\n}\nsyncTaskNavigation(selectedTask);\ndocument.addEventListener(\'change\', event => {if (event.target.id === \'task-choice\') syncTaskNavigation(event.target.value,true);});\nfor (const input of document.querySelectorAll(\'[data-filter-table]\')) input.addEventListener(\'input\', () => {\n  const table = document.getElementById(input.dataset.filterTable);\n  const term = input.value.toLocaleLowerCase();\n  for (const row of table.tBodies[0].rows) row.hidden = !row.textContent.toLocaleLowerCase().includes(term);\n});\n</script>'.replace('TASK', task_json)
    language_links = []
    for code, name in (('en', 'English'), ('zh', _ui('中文'))):
        parameters = parse_qs(split.query)
        parameters['lang'] = [code]
        if task_id:
            parameters['task'] = [task_id]
        destination = split.path + '?' + urlencode(parameters, doseq=True)
        language_links.append(f'''<a href="{esc(destination)}" hreflang="{code}"{(' aria-current="true"' if LANGUAGE.get() == code else '')}>{name}</a>''')
    language_switch = '<span class="language-switch" role="group" aria-label="Interface language">' + ''.join(language_links) + '</span>'
    return f"""<div class="app-shell"><aside class="sidebar"><a class="brand" href="/?{urlencode({'lang': LANGUAGE.get(), **({'task': task_id} if task_id else {})})}"><span class="brand-mark">{icon('molecule')}{_ui('</span><span><span class="brand-name">MAS Research</span><span class="brand-sub" style="display:block">EVIDENCE, INTO INSIGHT</span></span></a><div><div class="sidebar-heading">研究工作区</div><nav class="nav-list" aria-label="主导航">')}{''.join(nav)}{_ui('</nav></div><div class="sidebar-context"><div class="eyebrow">当前任务</div><strong id="sidebar-task" title="')}{esc(task_id)}">{esc(short(task_id))}{_ui('</strong><a href="/#tasks">切换研究任务 →</a></div><div class="sidebar-footer"><span class="dot"></span>本机研究工作台<br>数据来自可追溯的研究记录</div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">工作区 <span> / </span><strong>')}{esc(display_title)}</strong></div><div class="topbar-actions">{language_switch}{_ui('<span class="local-indicator">本机工作区</span></div></header><main id="main-content">')}{body}{footer}</main></div></div>{script}"""

def heading(title: str, subtitle: str, actions: str='') -> str:
    return f'<div class="page-heading"><div><div class="eyebrow">RESEARCH WORKSPACE</div><h1>{esc(title)}</h1><p>{esc(subtitle)}</p></div><div class="page-actions">{actions}</div></div>'

def button(label: str, href: Any, primary: bool=False) -> str:
    return f'''<a class="button{(' primary' if primary else '')}" href="{esc(href)}">{esc(label)}</a>''' if href else ''
STATUS = {'running': '运行中', 'completed': '已完成', 'failed': '运行失败', 'cancelled': '已终止', 'paused': '已暂停', 'unresolved': '待解决', 'proposed': '已提出', 'candidate': '候选', 'promoted': '已注册', 'merged_away': '已合并', 'withdrawn': '已撤回', 'filtered_out': '已筛除', 'needs_refine': '待完善', 'pass': '通过', 'fail': '未通过', 'unknown_missing': '证据缺失', 'unknown_unresolvable': '暂无法确定', 'recommended': '推荐', 'provisional': '暂定', 'rejected': '已排除', 'unassessed': '未评估', 'prespecified': '预先指定', 'exploratory': '探索性', 'open': '待复核', 'conditional': '有条件研究', 'scoring': '当前计分', 'registered': '已注册', 'retired': '已撤回', 'started': '已开始', 'queued': '等待中'}

def status(value: Any, label: Any=None) -> str:
    value = str(value or 'unknown')
    color = 'ok' if value in ('completed', 'pass', 'recommended', 'promoted', 'prespecified') else 'bad' if value in ('failed', 'fail', 'rejected') else 'warn' if value in ('running', 'paused', 'provisional', 'open', 'needs_refine') else 'neutral'
    return f'<span class="pill {color}" title="{esc(label or value)}">{esc(_ui(STATUS[value]) if value in STATUS else label or value)}</span>'

def number(value: Any, places: int=3) -> str:
    if value is None:
        return '—'
    return f'{value:.{places}f}' if isinstance(value, float) else str(value)

def cost_value(value: Any, accounting: str | None=None, places: int=4) -> str:
    if value is None or accounting == 'unknown':
        return _ui('未知')
    shown = f'${value:.{places}f}'
    return shown + ' · ' + _ui('已知小计') if accounting == 'partial' else shown

def usage_label(accounting: str | None) -> str:
    return {'complete': _ui('完整记录'), 'recorded': _ui('已记录'), 'partial': _ui('部分记录'), 'unknown': _ui('未知')}.get(accounting, _ui('已记录'))

def choice_label(key: str, value: Any) -> str:
    choices = {'search.volume': {'low': 'Light', 'mid': 'Medium', 'high': 'Extensive', 'xhigh': 'Very extensive'}, 'textbook.volume': {'low': 'Light', 'mid': 'Medium', 'high': 'Extensive', 'xhigh': 'Very extensive'}, 'budget.on_exhaust': {'finalize_partial': 'Stop and keep partial results', 'warn_continue': 'Warn and continue', 'ask': 'Ask before continuing', 'abort': 'Stop the run'}, 'interaction.mode': {'checkpoint': 'Pause at checkpoints', 'autonomous': 'Run automatically', 'interactive': 'Interactive guidance'}}
    return _ui_label(choices.get(key, {}).get(value, str(value)))

def role_label(value: Any) -> str:
    labels = {'reader': 'Evidence reader', 'retriever': 'Researcher', 'proposer': 'Planner', 'critic': 'Reviewer', 'adjudicator': 'Automated reviewer', 'summarizer': 'Summarizer'}
    return _ui_label(labels.get(value, str(value or '—')))

def percent(value: Any) -> str:
    return f'{value * 100:.0f}%' if isinstance(value, (float, int)) else '—'

def metrics(rows: list[tuple[str, Any, str]]) -> str:
    return '<div class="metrics">' + ''.join((f'<div class="metric"><span class="metric-label">{esc(label)}</span><strong class="metric-value">{esc(value)}</strong><div class="metric-note">{esc(note)}</div></div>' for label, value, note in rows)) + '</div>'

def card(title: str, body: str, subtitle: str='', action: str='') -> str:
    return f"""<section class="card"><div class="card-head"><div><h2>{esc(title)}</h2>{(f'<p>{esc(subtitle)}</p>' if subtitle else '')}</div>{action}</div><div class="card-body">{body}</div></section>"""

def table(headers: list[str], rows: list[list[str]], table_id: str='') -> str:
    if not rows:
        return _ui('<div class="empty">暂无已记录的数据。</div>')
    return f'<div class="table-wrap"><table id="{esc(table_id)}"><thead><tr>' + ''.join((f'<th>{esc(head)}</th>' for head in headers)) + '</tr></thead><tbody>' + ''.join(('<tr>' + ''.join((f'<td>{cell}</td>' for cell in row)) + '</tr>' for row in rows)) + '</tbody></table></div>'

def audit(data: dict[str, Any], title: str='完整记录与追溯信息') -> str:
    public = {key: value for key, value in data.items() if not str(key).startswith('_')}
    return f'<details class="audit"><summary>{esc(_ui(title))}</summary><pre>{esc(json.dumps(public, ensure_ascii=False, indent=2, default=str))}</pre></details>'

def search(table_id: str, placeholder: str) -> str:
    return f'''<div class="input-wrap search-input">{icon('search')}<label class="sr-only" for="filter-{table_id}">{esc(placeholder)}</label><input id="filter-{table_id}" type="search" data-filter-table="{table_id}" placeholder="{esc(placeholder)}"></div>'''

def home(data: dict[str, Any]) -> str:
    tasks, runs = (data.get('tasks', []), data.get('runs', []))
    active = [run for run in runs if run.get('state') in ('queued', 'running', 'paused')]
    latest = next((item for item in tasks if item['task_id'] == data.get('_navigation_task')), tasks[-1] if tasks else None)
    result = heading(_ui('研究工作台'), _ui('从研究目标到候选证据，在同一个工作区追踪每一步。'), button(_ui('配置研究工作区'), '/settings', True))
    if latest:
        result += f"""{_ui('<section class="card hero"><div><div class="eyebrow">当前研究 · TASK ')}{latest['version']}</div><h2 class="objective">{esc(latest['objective_text'])}</h2><div class="tags">{status(latest['mode'], latest['mode'])}<span class="pill">{esc(latest['universe_size'])}{_ui(' 个候选</span><span class="pill">')}{esc(latest['snapshots'])}{_ui(' 份结果快照</span></div></div><div class="hero-symbol">')}{icon('molecule')}</div></section>"""
    else:
        result += _ui('<div class="empty">工作区暂无研究任务。接入已有 store 后，任务与结果会显示在这里。</div>')
    result += metrics([(_ui('研究任务'), len(tasks), _ui('已记录的任务')), (_ui_label('Open run records'), len(active), _ui_label('Records marked queued, running or paused')), (_ui('结果快照'), sum((t['snapshots'] for t in tasks)), _ui('已发布的候选榜单')), (_ui('累计运行'), len(runs), _ui('包含完成、失败与中断'))])
    readings = data.get('published_readings') or {}
    primary = readings.get('primary_reading') or {}
    if primary and data.get('_navigation_task') == readings.get('task_id'):
        reference = primary.get('reference') or {}
        link = '/leaderboard?' + urlencode({'task': readings['task_id'], 'snapshot': primary['snapshot_id']})
        reference_name = (reference.get('identity_labels') or [_ui('参考候选')])[0]
        a = f"""{_ui('<div class="tags"><span class="pill ok">已记录 · 冻结读数</span></div><h3>')}{esc(reference_name)} #{esc(reference.get('position'))} / {esc(primary.get('rankable_n'))}{_ui('</h3><p class="note">全体候选 ')}{esc(primary.get('universe_n'))}{_ui(' · 偏好覆盖 ')}{percent(reference.get('preference_coverage'))}{_ui(' · 必需标准 ')}{esc(reference.get('n_mandated_answered'))}/{esc(reference.get('n_mandated'))}{_ui('</p><p class="note">缺失：')}{esc(', '.join(reference.get('mandated_blocked_by') or []) or _ui('无'))}</p>{button(_ui('查看固定榜单 →'), link)}"""
        old, new = (readings.get('original_cqa_reading') or {}, readings.get('new_cqa_reading') or {})
        old_n = old.get('exact_or_near', 0)
        new_n = new.get('exact', 0) + new.get('near_equivalent', 0)
        b = f"""{_ui('<div class="tags"><span class="pill neutral">描述性参考</span></div><h3>历史标准近似恢复 ')}{new_n}/{esc(new.get('total'))}{_ui('</h3><p class="note">原任务读数 ')}{old_n}/{esc(old.get('total'))}{_ui('。语义判定口径执行存在差异，两个读数不作直接增减比较。</p><p class="note">作为补充读数保留，不阻塞当前研究流程。</p>')}"""
        result += '<div class="grid2 equal">' + card(_ui('A · 参考候选排名'), a) + card(_ui('B · 历史标准恢复'), b) + '</div>'
    task_cards = []
    for item in reversed(tasks):
        task_cards.append(f"""<article class="task-card"><div class="tags">{status(item['mode'], item['mode'])}<span class="note">v{item['version']}</span></div><h3>{esc(item['objective_text'])}</h3><div class="meta-row"><span>{item['universe_size']}{_ui(' 个候选</span><span>')}{item['snapshots']}{_ui(' 份快照</span><span>')}{item['blocking_unknowns']}{_ui(' 个阻塞项</span></div><div class="card-bottom">')}{button(_ui('候选排名 →'), item['leaderboard'])}{button(_ui('研究标准'), item['pool'])}</div><span class="code">{esc(short(item['task_id']))}</span></article>""")
    result += '<div id="tasks">' + card(_ui('研究任务'), '<div class="task-grid">' + ''.join(task_cards) + '</div>' if task_cards else _ui('<div class="empty">暂无任务</div>'), _ui('选择任务查看标准、排名和证据')) + '</div>'
    rows = [[f'''<a class="row-title" href="{esc(row['run'])}">{esc(row.get('run_purpose_label') or _ui('研究运行'))}</a><div class="row-subtitle">{esc(short(row['run_id']))}</div>''', status(row.get('state'), row.get('state_label')), esc(row.get('rules@v')), esc(str(row.get('bound_at') or '—')[:19].replace('T', ' ')), esc(row.get('termination_reason_label') or '—'), button(_ui('查看 →'), row['run'])] for row in reversed(runs[-12:])]
    result += card(_ui('最近运行'), table([_ui('运行'), _ui_label('Recorded state'), _ui('规则集'), _ui('启动时间'), _ui('结果 / 终止原因'), ''], rows), _ui('保留每次运行的实际状态与结果'))
    return result + audit(data)

def leaderboard_page(data: dict[str, Any]) -> str:
    export = '/export/leaderboard.csv?' + urlencode({'task': data['task_id'], 'snapshot': data['snapshot_id']})
    result = heading(_ui('候选排名'), _ui('在同一冻结规则下比较候选，排名、证据覆盖与资格同时呈现。'), button(_ui('导出完整榜单'), export) + button(_ui('查看运行'), data.get('run')))
    result += metrics([(_ui('可排名候选'), data['rankable_set_size'], f"{_ui('共比较 ')}{data['members_compared']}{_ui(' 个候选')}"), (_ui('证据覆盖'), percent(data.get('coverage_fraction')), _ui('按当前榜单记录')), (_ui('评估完成度'), percent(data.get('sweep_completeness')), _ui('已完成评估 / 计划评估')), (_ui('冻结规则集'), data['rules@v'], data.get('acceptance_label_shown') or '')])
    result += f"""<div class="notice">{esc(_ui_label(data.get('mandated_coverage_note') or ''))}{_ui(' 排名覆盖门槛：')}{percent(data.get('ranking_coverage_floor'))}。</div>"""
    options = ''.join((f'''<option value="{esc(item['snapshot_id'])}"{(' selected' if item['snapshot_id'] == data['snapshot_id'] else '')}>{esc(item['published_at'][:19])} · {esc(short(item['snapshot_id']))}</option>''' for item in data.get('snapshots', [])))
    result += f'''<form method="get" action="/leaderboard" class="card operation-context"><input type="hidden" name="task" value="{esc(data['task_id'])}{_ui('"><div style="flex:1"><label for="snapshot-choice" style="margin-top:0">结果快照 · 每份读数独立保留</label><select id="snapshot-choice" name="snapshot">')}{options}{_ui('</select></div><button type="submit">查看此快照</button></form>')}'''
    rows = []
    for entry in data.get('rows', []):
        rows.append([f"""<span class="rank">{esc(entry.get('position') or '—')}</span>""", f'''<a class="row-title" href="{esc(entry['candidate'])}">{esc(entry.get('label') or entry['candidate_ref'])}</a><div class="row-subtitle code">{esc(entry['candidate_ref'])}</div>''', f"""<span class="score">{esc(number(entry.get('score')))}</span>""", percent(entry.get('preference_coverage')), status(entry.get('state'), entry.get('state_label')), _ui('通过') if entry.get('clears_mandated_criteria') is True else _ui('未满足') if entry.get('clears_mandated_criteria') is False else _ui('未规定'), button(_ui('证据 →'), entry['candidate'])])
    pagination = data.get('pagination') or {'page': 1, 'pages': 1, 'first_row': 1, 'last_row': data['rows_shown'], 'page_size': data['rows_shown']}
    toolbar = f"""<div class="search-row">{search('ranking-table', _ui('筛选本页候选名称或编号'))}{_ui('<span class="note">第 ')}{pagination['first_row']}–{pagination['last_row']}{_ui(' 条 / 共 ')}{data['members_compared']}{_ui(' 个候选</span></div>')}"""
    result += card(_ui('候选榜单'), toolbar + table([_ui('排名'), _ui('候选'), _ui('分数'), _ui('偏好覆盖'), _ui('状态'), _ui('必需标准资格'), ''], rows, 'ranking-table'), _ui('分数只来自已评估值；缺失状态保留在证据详情中。'))
    paging = []
    for label, page in ((_ui('← 上一页'), pagination['page'] - 1), (_ui('下一页 →'), pagination['page'] + 1)):
        if 1 <= page <= pagination['pages']:
            paging.append(button(label, '/leaderboard?' + urlencode({'task': data['task_id'], 'snapshot': data['snapshot_id'], 'top': pagination['page_size'], 'page': page})))
    result += _ui('<div class="search-row"><span class="note">第 ') + str(pagination['page']) + ' / ' + str(pagination['pages']) + _ui(' 页</span><div class="page-actions">') + ''.join(paging) + '</div></div>'
    return result + audit(data)

def run_page(data: dict[str, Any]) -> str:
    derivation = data.get('derivation')
    result = heading(_ui('标准流程监控') if derivation else _ui('运行监控'), _ui('追踪已记录的阶段、模型活动与预算。') if derivation else _ui('追踪已记录的执行进度、证据判定与预算。'), button(_ui('查看候选排名'), data.get('leaderboard')))
    result += f"""{_ui('<section class="card"><div class="card-head"><div><h2>研究运行 <span class="code">')}{esc(short(data['run_id']))}</span></h2><p>{esc(data.get('termination_reason_label') or _ui('等待下一条运行记录'))}</p></div>{status(data.get('state'), data.get('state_label'))}</div>"""
    progress = data.get('progress', [])
    if derivation:
        labels = {'reenter': _ui('接入待处理标准'), 'filter': _ui('筛查'), 'distill': _ui('提炼'), 'merge': _ui('合并'), 'refine': _ui('修订'), 'promote': _ui('注册')}
        current = derivation.get('current_stage')
        if current:
            result += f"""{_ui('<div class="notice">当前阶段：')}{esc(labels.get(current['stage'], current['stage']))}{_ui(' · 第 ')}{esc(current['iteration'])}{_ui(' 轮</div>')}"""
        stage_rows = [[esc(row.get('iteration')), esc(labels.get(row.get('stage'), row.get('stage'))), status(row.get('state')), esc(str(row.get('opened_at') or '—')[11:19]), esc(str(row.get('closed_at') or '—')[11:19])] for row in progress]
        result += table([_ui('迭代'), _ui('阶段'), _ui('状态'), _ui('开始'), _ui('完成')], stage_rows)
        result += f"""<p class="section-note">{esc(_ui_label(derivation['progress_note']))}</p>"""
        progress = []
    for row in progress:
        name = str(row.get('scope', ''))
        if 'percent' in row:
            value = max(0, min(100, row['percent']))
            result += f'''<div class="progress-meta"><span>{esc(name)}</span><span>{esc(row.get('completed'))} / {esc(row.get('planned'))} · {value:.0f}%</span></div><div class="progress-track" role="progressbar" aria-label="{esc(name)}" aria-valuenow="{value}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:{value}%"></div></div>'''
        else:
            result += f"""<div class="progress-meta"><span>{esc(name)}</span><span>{esc(row.get('completed'))}{_ui(' 已完成 · 总量未确定</span></div>')}"""
    result += '<div class="section-note">' + (_ui('运行中页面每 10 秒刷新。') if data.get('state') == 'running' else _ui('此运行已记录当前状态，刷新可读取最新记录。')) + '</div></section>'
    binding = data.get('binding', {})
    budget = data.get('budget') or {}
    if derivation:
        result += metrics([(_ui('当前迭代'), derivation.get('iteration'), f"{_ui('配置上限 ')}{derivation.get('iteration_limit') or '—'}{_ui(' 轮，可提前停止')}"), (_ui('已完成阶段'), sum((row['state'] == 'completed' for row in derivation['stages'])), _ui('按实际阶段结束记录')), (_ui('已记录估计费用'), cost_value((budget.get('used') or {}).get('usd'), budget.get('cost_status')), _ui('进行中的请求尚未计入')), (_ui('最近活动'), str(data.get('last_activity_at') or '—')[11:19], str(data.get('last_activity_at') or '')[:10])])
        usage_rows = [[esc(role_label(row['role'])), esc(row['finished_requests']), esc(row['input_tokens']), esc(row['output_tokens']), esc(usage_label(row.get('usage_status'))), esc(cost_value(row['estimated_cost_usd'], row.get('cost_status'), 6))] for row in derivation.get('model_usage_by_role', [])]
        result += card(_ui('已记录模型用量'), table([_ui('角色'), _ui('已完成请求'), _ui('输入 token'), _ui('输出 token'), _ui('记录状态'), _ui('估计费用')], usage_rows), _ui_label(budget.get('note') or ''))
        activity_rows = [[esc(role_label(row.get('role'))), esc(row.get('model_id')), status(row['state']), esc(str(row.get('at') or '—')[11:19]), esc(cost_value(row.get('estimated_cost_usd'), row.get('cost_status'), 6)) if row['state'] == 'completed' else _ui('等待完成记录')] for row in derivation.get('recent_model_activity', [])]
        result += '<p class="section-note">' + esc(_ui_label(budget.get('usage_note') or '')) + '</p>'
        result += card(_ui('最近模型活动'), table([_ui('角色'), _ui('模型'), _ui('事件'), _ui('时间'), _ui('估计费用')], activity_rows), _ui('只展示真实开始与完成记录。'))
    else:
        result += metrics([(_ui('冻结规则集'), binding.get('rules@v') or '—', _ui('此运行绑定的规则')), (_ui('固定种子'), binding.get('sweep_seed') if binding.get('sweep_seed') is not None else '—', _ui('可复现的候选顺序')), (_ui('判定数量'), sum((row['count'] for row in data.get('verdicts', []))), _ui('包含未知与失败状态')), (_ui('最近活动'), str(data.get('last_activity_at') or '—')[11:19], str(data.get('last_activity_at') or '')[:10])])
    verdicts = table([_ui('判定'), _ui('数量')], [[status(row['verdict'], row.get('label')), esc(row['count'])] for row in data.get('verdicts', [])])
    budget_labels = {'usd': _ui('模型估计费用（美元）'), 'input_tokens': _ui('已记录输入 token'), 'output_tokens': _ui('已记录输出 token'), 'model_requests_started': _ui('已开始请求'), 'model_requests_finished': _ui('已完成请求')}
    budget_rows = [[esc(budget_labels.get(key, key)), esc(value), esc((budget.get('limit') or budget.get('envelope') or {}).get(key))] for key, value in (budget.get('used') or {}).items()]
    result += card(_ui('预算记录'), table([_ui('资源'), _ui('已记录用量'), _ui('配置上限')], budget_rows), _ui_label(budget.get('note') or '')) if derivation else '<div class="grid2 equal">' + card(_ui('证据判定'), verdicts) + card(_ui('预算使用'), table([_ui('资源'), _ui('已使用'), _ui('上限')], budget_rows), _ui('资源与评估进度分别记录')) + '</div>'
    return result + audit(data)

def pool_page(data: dict[str, Any]) -> str:
    result = heading(_ui('研究标准'), _ui('查看继承标准的状态、支持证据与合并沿革。'), button(_ui('查看候选排名'), data.get('leaderboard')))
    counts = {r['state']: r['items'] for r in data.get('counts', [])}
    summary = data.get('registry_summary') or {}
    result += metrics([(_ui('当前保留标准'), summary.get('active_registered_count', '—'), f"{_ui('注册历史共 ')}{summary.get('registered_total', 0)}{_ui(' 条')}"), (_ui('当前计分标准'), summary.get('scoring_count', '—'), summary.get('rule_set_ref') or _ui('尚未冻结')), (_ui('待审标准'), summary.get('pending_count', '—'), _ui('当前保留标准中的待审项目')), (_ui('已撤回标准'), summary.get('retired_registered_count', '—'), _ui('撤回记录与原因保留'))])
    result += f"""<div class="notice">{esc(_ui_label(summary.get('note') or ''))}</div>"""
    reduction = summary.get('reduction') or {}
    if reduction.get('run_id'):
        reduction_states = reduction.get('scope_pool_states') or {}
        result += card(_ui('本次标准整理'), _ui('<div class="tags"><span class="pill">保留注册 ') + str(reduction.get('active_registered_count', 0)) + _ui('</span><span class="pill">活跃总量 ') + str(reduction.get('total_active_count', 0)) + _ui('</span><span class="pill">合并 ') + str(reduction_states.get('merged_away', 0)) + _ui('</span><span class="pill">本次撤回 ') + str(reduction.get('retired_by_this_run_count', 0)) + _ui('</span><span class="pill warn">未注册待处理 ') + str(reduction.get('additional_unregistered_active_count', 0)) + '</span></div>', _ui('活跃总量包含额外未注册的待处理条目。'), button(_ui('查看整理运行'), '/run?run=' + reduction['run_id']))
    result += card(_ui('标准整理与压缩'), _ui('<p class="note">先查看保留、合并与待审状态，再整理标准并冻结新的运行方案。已有榜单继续保留其原规则版本。</p>') + button(_ui('进入整理工作区 →'), '/operations?' + urlencode({'task': data['task_id']})), _ui('整理状态与计分集合独立展示'))
    registry_rows = [[f"""<span class="row-title">{esc(r.get('name'))}</span><div class="row-subtitle">{esc(r.get('definition'))}</div>""", status(r['state']), esc(r.get('unit')), esc(r.get('supporting_claims'))] for r in summary.get('registered_criteria', [])]
    result += card(_ui('注册标准'), f"""<div class="search-row">{search('registry-table', _ui('搜索标准名称或定义'))}<span class="note">{summary.get('registered_total', 0)}{_ui(' 条注册标准</span></div>')}""" + table([_ui('标准'), _ui('用途状态'), _ui('单位'), _ui('支持证据')], registry_rows, 'registry-table'))
    rows = []
    for row in data.get('items', []):
        detail = {key: row.get(key) for key in ('criterion_id', 'version', 'promoted_as', 'parents', 'children', 'last_change')}
        rows.append([f"""<span class="row-title">{esc(row.get('name') or row['criterion_id'])}</span><div class="row-subtitle">{esc(row.get('dimension'))}</div>""", status(row['state'], row.get('state_label')), esc(row.get('unit')), esc(row.get('supporting_claims')), esc(row.get('changes')), audit(detail, _ui('沿革与详情'))])
    pool_info = ' · '.join((f'{_ui(STATUS.get(key, key))} {value}' for key, value in counts.items()))
    result += f"{_ui('<details><summary>标准池沿革 · ')}{data['items_n']}{_ui(' 条历史条目 · ')}{esc(pool_info)}</summary>" + table([_ui('标准'), _ui('状态'), _ui('单位'), _ui('支持证据'), _ui('变更'), ''], rows, 'criteria-table') + '</details>'
    return result + audit(data)

def candidate_page(data: dict[str, Any]) -> str:
    result = heading(data.get('label') or _ui('候选与证据'), _ui('把候选的排名、标准判定与原始证据放在一起。'), button(_ui('返回候选排名'), data.get('leaderboard')))
    result += metrics([(_ui('排名'), f"#{data['position']}" if data.get('position') else _ui('未排名'), data.get('state_label') or ''), (_ui('偏好分数'), number(data.get('score')), _ui('按本次冻结规则计分')), (_ui('偏好证据覆盖'), percent(data.get('preference_coverage')), _ui('缺失值保留为未知')), (_ui('可追溯证据'), data.get('claims_admitted', 0), _ui('已接纳的证据记录'))])
    cells = [[f'''<div class="row-title">{esc(row.get('attribute_name') or row.get('attribute_ref'))}</div>''' + (f'''<div class="row-subtitle code">{esc(row.get('attribute_ref'))}</div>''' if row.get('attribute_name') else ''), f'''<span class="numeric">{esc(number(row.get('value')))}</span>''', f'''<span class="unit">{esc(row.get('unit'))}</span>''', status(row.get('verdict'), row.get('verdict_label')), esc(row.get('determination_basis')), esc(row.get('reason_text'))] for row in data.get('per_criterion', [])]
    result += card(_ui('逐项标准判定'), table([_ui('标准'), _ui('数值'), _ui('单位'), _ui('判定'), _ui('测定依据'), _ui('说明')], cells, 'candidate-criteria-table'))
    note = data.get('mechanism_of_action', {})
    sentences = note.get('sentences') or []
    explanation = ''.join((f"<p>{esc(row.get('text'))}</p>" for row in sentences)) if sentences else _ui('<div class="empty">当前尚无通过证据核验的作用机制解释。</div>')
    result += card(_ui('作用机制'), explanation, _ui('作用机制说明独立于排名与分数。'))
    claims = []
    for claim in data.get('claims', []):
        claims.append(f"""<article class="claim"><div class="tags"><span class="pill">{esc(claim.get('evidence_kind') or claim.get('claim_type') or _ui('证据'))}</span><span class="code">{esc(claim.get('locator'))}</span></div><blockquote>{esc(claim.get('quote') or claim.get('claim_text') or _ui('未记录引文'))}</blockquote><div class="note">{esc(claim.get('source_ref'))}</div></article>""")
    result += card(_ui('支持证据'), ''.join(claims) or _ui('<div class="empty">暂无已接纳证据。</div>'), _ui('引文来自记录中的来源与定位。'))
    return result + audit(data)

def review_page(data: dict[str, Any]) -> str:
    result = heading(_ui_label('Task review') if data.get('scope') == 'task' else _ui_label('Workspace review'), _ui_label('Review items for the selected task and its runs.') if data.get('scope') == 'task' else _ui('查看待处理项目、机器裁决与专家决定的实际记录。'), button(_ui('本机操作'), '/operations'))
    result += metrics([(_ui('待复核'), data['pending_n'], _ui('等待进一步处理的项目')), (_ui('阻塞项目'), data['blocking_n'], _ui('可能影响后续运行')), (_ui('机器已裁决'), data['machine_adjudicated_n'], _ui('保留机器裁决身份')), (_ui('专家已决定'), len(data.get('decided', [])), _ui('来自真实专家决定'))])
    rows = [[esc(row.get('subject_id')), esc(row.get('subject_kind')), status(row['state'], row.get('state_label')), esc(row.get('why_expert_required')), audit(row, _ui('处理路径'))] for row in data.get('pending', [])]
    result += card(_ui('待处理项目'), table([_ui('项目'), _ui('类型'), _ui('状态'), _ui('复核原因'), ''], rows), _ui('专家决定通过终端录入；指定项目的机器裁决可从本机操作面板提交。'))
    if data.get('machine_adjudicated'):
        result += card(_ui('机器裁决记录'), table([_ui('项目'), _ui('裁决路径'), _ui('处理结果')], [[esc(r.get('subject_id')), esc(r.get('route_label')), esc(r.get('resolution'))] for r in data['machine_adjudicated']]), _ui('这些记录保持机器裁决身份。'))
    if data.get('historical'):
        rows = [[esc(row['subject_id']), esc(row['subject_kind']), status(row['state'], row.get('state_label')),
                 audit(row, _ui('记录详情'))] for row in data['historical']]
        result += '<details><summary>' + esc(_ui('旧版本复核记录')) + f" · {data['historical_n']}" + '</summary><p class="note">' + esc(_ui('这些标准版本已被更新或撤回，原复核状态保留，不计入当前待审与阻塞项目。')) + '</p>' + table([_ui('项目'), _ui('类型'), _ui('已记录状态'), ''], rows) + '</details>'
    if data.get('routes_included') is False:
        result += '<details><summary>' + esc(_ui_label('Review options')) + '</summary>' + button(_ui_label('Load automated review routes'), '/review?' + urlencode({'routes': 1, **({'task': data['task_id']} if data.get('task_id') else {})})) + '</details>'
    return result + audit(data)

def settings_page(data: dict[str, Any]) -> str:
    result = heading(_ui('工作区设置'), _ui('了解当前配置、模型分工与参数来源。'))
    result += metrics([(_ui('当前预设'), data.get('preset') or 'standard', _ui('服务启动时解析')), (_ui('模型角色'), len(data.get('role_bindings', [])), _ui('当前模型分工')), (_ui('配置参数'), len(data.get('settings', [])), _ui('包含每个参数的来源')), (_ui('配置档案'), data.get('profile') or _ui('默认'), _ui('可复用的工作区设置'))])
    editable = data.get('editable_configuration')
    if editable:
        fields = []
        for field in editable['fields']:
            identifier = 'setting-' + field['key'].replace('.', '-')
            attrs = f'''id="{identifier}" name="{esc(field['key'])}" data-kind="{field['kind']}"'''
            if field.get('choices'):
                options = ''.join((f'''<option value="{esc(choice)}"{(' selected' if choice == field['value'] else '')}>{esc(choice_label(field['key'], choice))}</option>''' for choice in field['choices']))
                control = f'<select {attrs}>{options}</select>'
            else:
                constraints = ''.join((f' {key}="{field[source]}"' for key, source in (('min', 'minimum'), ('max', 'maximum')) if field.get(source) is not None))
                step = 'any' if field['kind'] == 'float' else '1'
                control = f'''<input {attrs} type="number" step="{step}" value="{esc(field['value'])}"{constraints} required>'''
            fields.append(f'''<div><label for="{identifier}">{esc(_ui_label(field['label']))}</label>{control}</div>''')
        form = _ui('<form id="settings-form"><div class="notice">默认采用标准方案与适中的文献、教材阅读量。更改仅用于后续工作，已有结果保持原设置。</div><div class="controls">') + ''.join(fields) + _ui('</div><div class="page-actions" style="margin-top:20px"><button class="primary" type="submit">保存配置</button>') + button(_ui('选择任务并继续 →'), '/operations') + '</div><p id="settings-message" class="note" role="status" aria-live="polite"></p></form>'
        result += card(_ui('运行配置'), form, _ui('设置检查通过后保存到本机，用于后续工作。'))
        token = json.dumps(data.get('_operation_token') or '')
        result += _ui('<script type="module">\nconst form=document.getElementById(\'settings-form\');\nform.addEventListener(\'submit\',async event=>{\nevent.preventDefault();const output=document.getElementById(\'settings-message\');const submit=form.querySelector(\'button[type=submit]\');submit.disabled=true;\nconst settings={};for(const field of form.querySelectorAll(\'[data-kind]\')) settings[field.name]=[\'int\',\'float\'].includes(field.dataset.kind)?Number(field.value):field.value;\ntry{const response=await fetch(\'/api/operations\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\',\'X-MAS-Operation-Token\':TOKEN},body:JSON.stringify({action:\'save_settings\',settings})});const data=await response.json();if(!response.ok)throw new Error(data.message||data.error);output.textContent=\'设置已保存。请选择任务继续。\';}\ncatch(error){output.textContent=\'保存失败：\'+error.message;}finally{submit.disabled=false;}\n});</script>').replace('TOKEN', token)
    bindings = data.get('role_bindings', [])
    result += card(_ui('模型与角色'), table([_ui('角色'), _ui('模型'), _ui('提供方')], [[esc(role_label(row.get('role'))), esc(row.get('model_id')), esc(row.get('provider_family') or row.get('adapter_id'))] for row in bindings]), _ui('凭据仅显示读取方式，页面不会读取密钥。'))
    groups = {}
    for row in data.get('settings', []):
        groups.setdefault(row['key'].split('.')[0], []).append(row)
    labels = {'search': _ui('证据检索'), 'read': _ui('阅读与提取'), 'criteria': _ui('标准构建'), 'rank': _ui('候选排序'), 'budget': _ui('预算与资源'), 'interaction': _ui('交互与权限'), 'assess': _ui('候选评估'), 'sources': _ui('数据来源'), 'run': _ui('运行参数'), 'sr': _ui('评分表达式'), 'predict': _ui('预测工具'), 'concurrency': _ui_label('Parallel work'), 'evidence': _ui_label('Evidence checks'), 'textbook': _ui_label('Textbook reading')}
    for group, rows in groups.items():
        body = ''.join((f"""<div class="setting-row"><div><div class="setting-key">{esc(row['key'])}</div><div class="setting-doc">{esc(row.get('doc'))}</div></div><div>{esc(row['value'])}</div><span class="pill neutral">{esc(row['layer'])}</span></div>""" for row in rows))
        result += f"""<details class="setting-section"><summary>{esc(labels.get(group, group))} · {len(rows)}{_ui(' 项参数</summary>')}{body}</details>"""
    return result + audit(data, _ui('配置来源、提供方与完整记录'))

def render(target: str, data: dict[str, Any]) -> str:
    renderer = {'/': home, '/leaderboard': leaderboard_page, '/candidate': candidate_page, '/run': run_page, '/pool': pool_page, '/review': review_page, '/settings': settings_page}.get(urlsplit(target).path.rstrip('/') or '/')
    return empty_page(data) if data.get('empty_state') else renderer(data) if renderer else heading(TITLES.get(data.get('page'), data.get('page', _ui('工作台'))), '') + audit(data)

def operations_page(token: str) -> str:
    result = heading(_ui('运行工作区'), _ui('选择任务，整理标准，冻结方案，再完整运行。每个新读数拥有独立记录。'), button(_ui('配置与模型'), '/settings'))
    result += _ui('<section class="card"><div class="card-head"><div><h2>当前研究任务</h2><p>从已有任务继承一个新实验，保留已完成结果。</p></div><span class="pill">本机操作已启用</span></div>\n<div class="operation-select"><label for="task-choice">选择当前任务</label><select id="task-choice"></select></div><p id="task-detail" class="note"></p><div id="task-run-panel" class="notice" hidden><span id="task-run-state"></span> <a id="task-run-link" class="button" href="/run">查看当前运行 →</a></div>\n<details><summary>从当前任务创建新实验</summary><form id="inherit-form"><label for="inherit-reason">新实验目的</label><input id="inherit-reason" value="Inherit existing criteria and evidence for a new review and evaluation" required><button type="submit">创建继承任务</button></form><p class="note">新任务会继承现有记录，原任务的榜单和冻结方案继续保留。</p></details>\n<div class="stage-flow"><div class="stage"><span class="stage-number">01</span><a href="/settings">配置工作区</a><small>standard · mid 资源量</small></div><div class="stage"><span class="stage-number">02</span><a id="view-criteria" href="/#tasks">整理研究标准</a><small>注册、计分与待审分别统计</small></div><div class="stage"><span class="stage-number">03</span><a href="#supplement-panel">已核验补证</a><small>选择真实测量来源</small></div><div class="stage"><span class="stage-number">04</span><a href="#freeze-panel">冻结测量方案</a><small>记录本次规则与政策</small></div><div class="stage"><span class="stage-number">05</span><a href="#run-panel">运行并查看结果</a><small>固定方案 · 可追溯证据</small></div></div></section>\n<div class="metrics"><div class="metric"><span class="metric-label">当前保留标准</span><strong class="metric-value" id="registered-count">—</strong><div class="metric-note">整理前后保持真实计数</div></div><div class="metric"><span class="metric-label">当前计分标准</span><strong class="metric-value" id="scoring-count">—</strong><div class="metric-note" id="scoring-ref">—</div></div><div class="metric"><span class="metric-label">待审项目</span><strong class="metric-value" id="pending-count">—</strong><div class="metric-note">未结清的复核记录</div></div><div class="metric"><span class="metric-label">已撤回标准</span><strong class="metric-value" id="merged-count">—</strong><div class="metric-note">合并沿革独立保留</div></div></div>\n<section class="card" id="reduce-panel"><div class="card-head"><div><h2>02 · 整理研究标准</h2><p>系统在现有标准上整理，结果会给出保留、合并、撤回和待审计数。</p></div><a id="criteria-detail" href="/#tasks">查看全部标准 →</a></div>\n<form id="reduce-form"><label for="reduce-reason">整理目的</label><input id="reduce-reason" value="Reduce redundancy while preserving scientific meaning and evidence provenance" required><button id="start-reduce" type="submit" disabled>整理标准</button><span class="note" id="reduce-availability">正在读取系统能力…</span></form></section>\n<section class="card" id="supplement-panel"><div class="card-head"><div><h2>03 · 添加已核验的测量</h2><p>准备评估前，可添加已核验的测量。</p></div></div>\n<form id="supplement-form"><label for="supplement-choice">选择已核验来源</label><select id="supplement-choice"></select><p id="supplement-detail" class="note"></p><details id="supplement-provenance"><summary>来源说明</summary><p id="supplement-selection" class="note"></p></details><p id="supplement-state" class="note"></p><button type="submit" id="attach-supplement" disabled>添加选择的测量</button></form><p class="section-note">仅复用确切化合物与靶点对应的测量。排除记录保留，缺失状态继续如实呈现。</p></section>\n<div class="controls"><section class="card" id="freeze-panel"><div class="card-head"><div><h2>04 · 冻结测量方案</h2><p>为本次新读数固定规则、证据范围和排名政策。</p></div></div>\n<form id="freeze-form"><label for="board-name">结果名称</label><input id="board-name" value="Evaluation after criterion review" required><label for="freeze-rationale">方案依据</label><input id="freeze-rationale" value="Inherit existing evidence and save a new evaluation under the current settings" required><label for="freeze-effect">预期作用</label><input id="freeze-effect" value="Assess the complete candidate set and report rank, coverage, eligibility and unknowns separately" required>\n<details><summary>证据范围与延后能力</summary><label><input id="defer-literature" type="checkbox" checked style="width:auto"> 此次延后文献检索</label><label><input id="defer-predicted" type="checkbox" checked style="width:auto"> 此次延后预测属性</label><label for="defer-reason">延后理由</label><input id="defer-reason" value="Use inherited measurements for this reading and reserve prediction or retrieval for separate follow-up work"></details>\n<button class="primary" type="submit" id="prepare-evaluation" disabled>冻结本次方案</button><p id="prepare-active-hint" class="note" hidden>已有运行正在进行。 <a id="prepare-active-run" href="/run">查看当前运行 →</a></p><p class="operation-form-note">冻结后配置变化会触发漂移检查。需要改变政策时，创建新的方案。</p></form></section>\n<section class="card" id="run-panel"><div class="card-head"><div><h2>05 · 完整运行</h2><p>只使用选择的冻结方案，候选结果可逐项追溯。</p></div></div>\n<form id="run-form"><label for="measurement-profile">选择测量方案</label><select id="measurement-profile" required></select><p id="profile-detail" class="note"></p><label for="frozen-ref">冻结规则集</label><input id="frozen-ref" readonly required><label for="workers">并发候选数</label><input id="workers" type="number" min="1" max="32" value="4" required><div class="notice">完整候选范围 · 固定 seed = 0。运行可能访问证据服务并产生模型费用，实际使用会记录在预算中。</div><button class="primary" type="submit" id="start-run">开始完整运行</button></form></section></div>\n<p id="operation-message" class="notice" role="status" aria-live="polite" hidden></p>\n<section class="card" style="margin-top:24px"><div class="card-head"><div><h2>运行与操作记录</h2><p>真实进程状态、退出码和结果链接。</p></div><button id="refresh-jobs" type="button">刷新</button></div><div id="job-list"><div class="empty">正在读取操作状态…</div></div></section>\n<details><summary>单项机器裁决与运行身份</summary><p class="note" id="operation-context"></p><form id="adjudicate-form"><label for="review-item">复核项 ID 或规则引用</label><input id="review-item" placeholder="从复核队列选择对应项目" required><button type="submit">提交机器裁决</button></form><p class="note">机器裁决按 agent_verdict 记录；专家审批由终端录入。</p></details>\n<script type="module">\nconst token=TOKEN;\nconst choice=document.getElementById(\'task-choice\'), message=document.getElementById(\'operation-message\'), profile=document.getElementById(\'measurement-profile\');\nlet state={tasks:[],jobs:[]},submitting=false,lastTask=\'\';const handled=new Set(),submittedInheritJobs=new Set();\nconst names={run_start:\'完整运行\',adjudicate_item:\'机器裁决\',task_inherit:\'创建继承任务\',freeze_profile:\'冻结方案\',reduce_registered:\'整理标准\',supplement_attach:\'附着测量补证\'};\nconst statuses={running:\'运行中\',completed:\'已完成\',failed:\'失败\',cancelled:\'已终止\',paused:\'已暂停\',queued:\'等待中\'};\nfunction show(text){message.hidden=false;message.textContent=text;}\nfunction hasActiveRun(){return !!state.tasks.find(t=>t.task_id===choice.value)?.active_run;}\nfunction profileChanged(){const selected=state.tasks.find(t=>t.task_id===choice.value);const item=(selected?.criteria_summary?.measurement_profiles||[]).find(p=>p.ref===profile.value);document.getElementById(\'frozen-ref\').value=item?.rule_set_ref||selected?.rule_set_ref||\'\';document.getElementById(\'profile-detail\').textContent=item?`${item.name||\'测量方案\'} · ${item.rank_endpoint||\'\'}`:\'先冻结一个新的测量方案，再开始运行。\';document.getElementById(\'start-run\').disabled=!item||!!selected?.blocking_unknowns||submitting||(state.jobs.some(j=>j.status===\'running\')||hasActiveRun());}\nfunction supplementChanged(){\nconst task=state.tasks.find(t=>t.task_id===choice.value),picker=document.getElementById(\'supplement-choice\');\nconst item=(state.verified_supplements||[]).find(s=>s.ref===picker.value);const attached=task?.verified_supplement_refs||[];\ndocument.getElementById(\'supplement-detail\').textContent=item?`${item.source_ref} · 接纳 ${item.accepted_count} 条测量，排除 ${item.excluded_count} 条。`:\'暂无可选择的已核验测量来源。\';document.getElementById(\'supplement-selection\').textContent=item?.selection?.rationale||\'\';document.getElementById(\'supplement-provenance\').hidden=!item;\nconst frozen=!!task?.criteria_summary?.measurement_profiles?.length;\ndocument.getElementById(\'supplement-state\').textContent=frozen?\'此任务已有冻结方案，创建新的继承任务后再附着补证。\':`${attached.length} 份来源已添加。`;\ndocument.getElementById(\'attach-supplement\').disabled=!item||frozen||attached.includes(item.ref)||submitting||(state.jobs.some(j=>j.status===\'running\')||hasActiveRun());\n}\nfunction taskChanged(){\nconst task=state.tasks.find(t=>t.task_id===choice.value),summary=task?.criteria_summary||{};const changed=lastTask!==choice.value;lastTask=choice.value;\ndocument.getElementById(\'task-detail\').textContent=task?.objective||\'此 store 暂无任务。\';\nconst live=task?.active_run;document.getElementById(\'task-run-panel\').hidden=!live;if(live){document.getElementById(\'task-run-state\').textContent=statuses[live.state]||live.state;document.getElementById(\'task-run-link\').href=live.run_url;}document.getElementById(\'prepare-evaluation\').disabled=!task||submitting||hasActiveRun()||state.jobs.some(j=>j.status===\'running\');document.getElementById(\'prepare-active-hint\').hidden=!live;if(live)document.getElementById(\'prepare-active-run\').href=live.run_url;\nfor(const [id,key] of [[\'registered-count\',\'active_registered_count\'],[\'scoring-count\',\'scoring_count\'],[\'pending-count\',\'pending_count\'],[\'merged-count\',\'retired_registered_count\']])document.getElementById(id).textContent=summary[key]??\'—\';\ndocument.getElementById(\'scoring-ref\').textContent=summary.rule_set_ref||\'尚未冻结\';\nfor(const id of [\'view-criteria\',\'criteria-detail\'])document.getElementById(id).href=\'/pool?task=\'+encodeURIComponent(choice.value);\nconst selectedProfile=changed?\'\':profile.value;profile.replaceChildren();const placeholder=new Option(\'请选择尚未绑定运行的方案\',\'\');profile.append(placeholder);\nfor(const item of summary.measurement_profiles||[]){const option=new Option((item.name||\'测量方案\')+\' · \'+item.rule_set_ref+(item.used_by_run?\'（已运行）\':\'\'),item.ref);option.disabled=!!item.used_by_run;profile.append(option);}\nif([...profile.options].some(o=>o.value===selectedProfile&&!o.disabled))profile.value=selectedProfile;else{const available=[...profile.options].filter(o=>o.value&&!o.disabled);if(available.length)profile.value=available.at(-1).value;}\nconst canReduce=(state.available_actions||[]).includes(\'reduce_registered\')&&!task?.rule_set_ref;document.getElementById(\'start-reduce\').disabled=!canReduce||submitting||(state.jobs.some(j=>j.status===\'running\')||hasActiveRun());document.getElementById(\'reduce-availability\').textContent=canReduce?\'按现有证据整理；实际结果将保留记录。\':task?.rule_set_ref?\'此任务已有冻结结果，先在上方创建继承任务再整理。\':\'标准整理接口暂未启用。\';\nif(changed){const workers=state.configuration?.fields?.find(f=>f.key===\'assess.workers\');if(workers)document.getElementById(\'workers\').value=workers.value;}\nconst picker=document.getElementById(\'supplement-choice\'),selectedSupplement=picker.value;picker.replaceChildren();\nfor(const item of state.verified_supplements||[]){const attached=(task?.verified_supplement_refs||[]).includes(item.ref);const option=new Option(`${item.source_ref} · 接纳 ${item.accepted_count} / 排除 ${item.excluded_count}${attached?\'（已附着）\':\'\'}`,item.ref);option.disabled=attached;picker.append(option);}\nif([...picker.options].some(o=>o.value===selectedSupplement&&!o.disabled))picker.value=selectedSupplement;else{const available=[...picker.options].find(o=>!o.disabled);if(available)picker.value=available.value;}\nsupplementChanged();profileChanged();}\nfunction renderJobs(){const list=document.getElementById(\'job-list\');list.replaceChildren();if(!state.jobs.length){const empty=document.createElement(\'div\');empty.className=\'empty\';empty.textContent=\'尚未从此工作区启动操作。\';list.append(empty);return;}\nconst current=state.jobs.filter(j=>j.task_id===choice.value),others=state.jobs.filter(j=>j.task_id!==choice.value);if(!current.length){const empty=document.createElement(\'div\');empty.className=\'empty\';empty.textContent=\'此任务还没有操作记录。\';list.append(empty);}const archive=document.createElement(\'details\'),archiveTitle=document.createElement(\'summary\');archiveTitle.textContent=\'工作区历史\';archive.append(archiveTitle);for(const job of [...current,...others]){const card=document.createElement(\'section\');card.className=\'card job-card\';const head=document.createElement(\'div\');head.className=\'job-header\';const title=document.createElement(\'h3\');title.textContent=names[job.action]||job.action;const badge=document.createElement(\'span\');badge.className=\'pill \'+(job.status===\'failed\'?\'bad\':job.status===\'completed\'?\'ok\':\'warn\');badge.textContent=statuses[job.status]||job.status;head.append(title,badge);card.append(head);const meta=document.createElement(\'div\');meta.className=\'job-meta\';meta.textContent=job.started_at.slice(0,19).replace(\'T\',\' \')+\' UTC\';card.append(meta);\nif(job.research_result_saved){const notice=document.createElement(\'p\');notice.className=\'notice\';notice.textContent=\'结果已保存，命令随后失败。\';card.append(notice);}\nif(job.run_url){const link=document.createElement(\'a\');link.className=\'button\';link.href=job.run_url;link.textContent=job.research_result_saved?\'查看已保存结果 →\':\'查看进度与结果 →\';card.append(link);}if(job.status===\'running\'){const cancel=document.createElement(\'button\');cancel.type=\'button\';cancel.className=\'cancel\';cancel.textContent=\'终止此进程\';cancel.onclick=()=>submit({action:\'cancel\',job_id:job.job_id});card.append(cancel);}\nconst details=document.createElement(\'details\'),summary=document.createElement(\'summary\'),log=document.createElement(\'pre\'),path=document.createElement(\'p\');summary.textContent=\'日志与追溯信息\';log.textContent=job.log_tail||\'等待进程输出…\';path.className=\'code\';path.textContent=`PID ${job.pid} · 退出码 ${job.exit_code??\'—\'}\\n${job.log_path}`;details.append(summary,path,log);card.append(details);(job.task_id===choice.value?list:archive).append(card);}if(others.length)list.append(archive);}\nasync function api(body){const response=await fetch(\'/api/operations\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\',\'X-MAS-Operation-Token\':token},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw new Error(data.message||data.error);return data;}\nasync function refresh(){try{const response=await fetch(\'/api/operations\',{cache:\'no-store\'});const data=await response.json();if(!response.ok)throw new Error(data.message||data.error);const old=choice.value;state=data;choice.replaceChildren();for(const task of state.tasks){const label=task.objective.slice(0,64)+(task.objective.length>64?\'…\':\'\')+\' · \'+task.task_id.slice(-5);choice.append(new Option(label,task.task_id));}const requested=new URLSearchParams(location.search).get(\'task\');choice.value=[old,requested,state.current_task,state.tasks.at(-1)?.task_id].find(id=>state.tasks.some(t=>t.task_id===id))||\'\';document.getElementById(\'operation-context\').textContent=`记录身份：${state.initiator.kind} / ${state.initiator.id}`;taskChanged();renderJobs();\nfor(const job of state.jobs){if(job.status===\'completed\'&&!handled.has(job.job_id)){handled.add(job.job_id);const newTask=job.action===\'task_inherit\'&&submittedInheritJobs.has(job.job_id)?(job.result?.task_id||job.result?.new_task_id):null;if(newTask&&state.tasks.some(t=>t.task_id===newTask)){choice.value=newTask;await api({action:\'select_task\',task_id:newTask});choice.dispatchEvent(new Event(\'change\',{bubbles:true}));}}}\n}catch(error){show(\'状态读取失败：\'+error.message);}}\nasync function submit(body){if(submitting)return;submitting=true;taskChanged();show(\'正在提交…\');try{const result=await api(body);if(body.action===\'task_inherit\'&&result.job_id){submittedInheritJobs.add(result.job_id);handled.delete(result.job_id);}show(result.job_id?`${names[body.action]||\'操作\'}已启动 · PID ${result.pid}`:\'已保存当前任务。\');await refresh();}catch(error){show(\'提交失败：\'+error.message);}finally{submitting=false;taskChanged();}}\nchoice.addEventListener(\'change\',()=>{taskChanged();renderJobs();api({action:\'select_task\',task_id:choice.value}).catch(error=>show(\'任务保存失败：\'+error.message));});profile.onchange=profileChanged;\ndocument.getElementById(\'inherit-form\').onsubmit=event=>{event.preventDefault();submit({action:\'task_inherit\',task_id:choice.value,reason:document.getElementById(\'inherit-reason\').value.trim()});};\ndocument.getElementById(\'supplement-choice\').onchange=supplementChanged;\ndocument.getElementById(\'supplement-form\').onsubmit=event=>{event.preventDefault();submit({action:\'supplement_attach\',task_id:choice.value,supplement_ref:document.getElementById(\'supplement-choice\').value});};\ndocument.getElementById(\'freeze-form\').onsubmit=event=>{event.preventDefault();const deferred=[];if(document.getElementById(\'defer-literature\').checked)deferred.push(\'literature_retrieval\');if(document.getElementById(\'defer-predicted\').checked)deferred.push(\'predicted_property_lookup\');submit({action:\'freeze_profile\',task_id:choice.value,primary_board:document.getElementById(\'board-name\').value.trim(),rationale:document.getElementById(\'freeze-rationale\').value.trim(),expected_effect:document.getElementById(\'freeze-effect\').value.trim(),defer_capabilities:deferred,defer_reason:document.getElementById(\'defer-reason\').value.trim()});};\ndocument.getElementById(\'run-form\').onsubmit=event=>{event.preventDefault();submit({action:\'run_start\',task_id:choice.value,rule_set_ref:document.getElementById(\'frozen-ref\').value,measurement_profile:profile.value,workers:Number(document.getElementById(\'workers\').value)});};\ndocument.getElementById(\'reduce-form\').onsubmit=event=>{event.preventDefault();submit({action:\'reduce_registered\',task_id:choice.value,reason:document.getElementById(\'reduce-reason\').value.trim()});};\ndocument.getElementById(\'adjudicate-form\').onsubmit=event=>{event.preventDefault();submit({action:\'adjudicate_item\',task_id:choice.value,item:document.getElementById(\'review-item\').value.trim()});};\ndocument.getElementById(\'refresh-jobs\').onclick=refresh;refresh();setInterval(refresh,5000);\n</script>').replace('TOKEN', json.dumps(token))
    return result

def empty_page(data: dict[str, Any]) -> str:
    title = TITLES.get(data.get('page'), 'Workspace')
    actions = button(_ui('运行与操作'), data.get('workspace')) + button(_ui('选择当前任务'), data.get('tasks_url') or '/')
    return heading(_ui(title), '', actions) + card(_ui(title), '<div class="empty">' + esc(_ui_label(data.get('message', ''))) + '</div>')
